class ListNode:
    def __init__(self, val, next=None):
        self.val = val
        self.next = next


def arr_to_list(arr):
    head = None
    tail = None
    for v in arr:
        node = ListNode(v)
        if not head:
            head, tail = node, node
        else:
            tail.next = node
            tail = node
    return head


def list_to_arr(head):
    result = []
    node = head
    while node:
        result.append(node.val)
        node = node.next
    return result


def merge(l1, l2):
    dummy = ListNode(0)
    tail = dummy
    while l1 and l2:
        if l1.val <= l2.val:
            tail.next = l1
            l1 = l1.next
        else:
            tail.next = l2
            l2 = l2.next
        tail = tail.next
    tail.next = l1 if l1 else l2
    return dummy.next


def merge_sort(node):
    if not node or not node.next:
        return node

    slow, fast = node, node.next
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next

    second = slow.next
    slow.next = None

    left = merge_sort(node)
    right = merge_sort(second)
    return merge(left, right)


def sort_list(head_arr):
    head = arr_to_list(head_arr)
    return list_to_arr(merge_sort(head))

